-- Q04 · O controlo de acesso do staging ficou exatamente igual.
-- Substituir __IMPRESSAO_ACL_STAGING_P03__ pelo valor GUARDADO de P03-15.
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH pf AS (SELECT p.oid, p.proname::text AS nome, p.pronargs, p.prosrc, p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public'),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q04-00'::text, 'marcador substituído'::text, ('__IMPRESSAO_ACL_STAGING_P03__' ~ '^[0-9a-f]{32}$')::boolean, 'md5'::text, ('ver comentário do ficheiro')::text
  UNION ALL SELECT 'Q04-01'::text, 'has_staging_access: corpo igual ao da migração 0000'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_staging_access') = '4376edeea92abf14230207df0fbbef11')::boolean, '4376edeea92abf14230207df0fbbef11'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_staging_access'))::text
  UNION ALL SELECT 'Q04-02'::text, 'has_role: NÃO substituída (corpo da migração 0000)'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_role') = '6b9bca1cc09de70841cac113efbdd41a')::boolean, '6b9bca1cc09de70841cac113efbdd41a'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_role'))::text
  UNION ALL SELECT 'Q04-03'::text, 'permissões de staging_notes/user_roles/has_role/has_staging_access iguais a P03'::text, (md5(coalesce((SELECT string_agg(c.relname::text || '=' || coalesce(c.relacl::text, 'NULL'), ';' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')), '') || '|' || coalesce((SELECT string_agg(p.proname::text || '=' || coalesce(p.proacl::text, 'NULL'), ';' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')), '')) = '__IMPRESSAO_ACL_STAGING_P03__')::boolean, '= P03-15'::text, (md5(coalesce((SELECT string_agg(c.relname::text || '=' || coalesce(c.relacl::text, 'NULL'), ';' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')), '') || '|' || coalesce((SELECT string_agg(p.proname::text || '=' || coalesce(p.proacl::text, 'NULL'), ';' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')), '')))::text
  UNION ALL SELECT 'Q04-04'::text, 'staging_notes: mesmas 3 notas'::text, ((SELECT md5(string_agg(title || '|' || body || '|' || synthetic::text, E'\n' ORDER BY title COLLATE "C")) FROM public.staging_notes) = '9839c85692f965b4f419fb33c6af3404' AND (SELECT count(*) FROM public.staging_notes) = 3)::boolean, '3 / 9839c85692f965b4f419fb33c6af3404'::text, ((SELECT count(*) FROM public.staging_notes)::text || ' / ' || (SELECT md5(string_agg(title || '|' || body || '|' || synthetic::text, E'\n' ORDER BY title COLLATE "C")) FROM public.staging_notes))::text
  UNION ALL SELECT 'Q04-05'::text, 'políticas de staging_notes e user_roles = só as originais (sem barreira V2 nem políticas de admin V2)'::text, (coalesce((SELECT array_agg(tablename::text || '.' || policyname::text ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')), '{}') = ARRAY['staging_notes.Staging members read notes', 'user_roles.Users read own roles'])::boolean, 'staging_notes.Staging members read notes,user_roles.Users read own roles'::text, ((SELECT string_agg(tablename::text || '.' || policyname::text, ',' ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')))::text
  UNION ALL SELECT 'Q04-06'::text, 'user_roles: colunas id,user_id,role,created_at,created_by'::text, ((SELECT string_agg(a.attname::text, ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attnum > 0 AND NOT a.attisdropped) = 'id,user_id,role,created_at,created_by')::boolean, 'id,user_id,role,created_at,created_by'::text, ((SELECT string_agg(a.attname::text, ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attnum > 0 AND NOT a.attisdropped))::text
  UNION ALL SELECT 'Q04-07'::text, 'user_roles.created_by: uuid, nulo, sem valor por omissão'::text, (EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attname = 'created_by' AND a.atttypid = 'uuid'::regtype AND NOT a.attnotnull AND NOT a.atthasdef))::boolean, 'sim'::text, ((SELECT format_type(a.atttypid, a.atttypmod) || ' notnull=' || a.attnotnull::text || ' default=' || a.atthasdef::text FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attname = 'created_by'))::text
  UNION ALL SELECT 'Q04-08'::text, 'user_roles: restrições inalteradas (sem chave nova)'::text, ((SELECT string_agg(x.conname::text, ',' ORDER BY x.conname COLLATE "C") FROM pg_constraint x WHERE x.conrelid = to_regclass('public.user_roles') AND x.contype <> 'n') = 'user_roles_pkey,user_roles_user_id_fkey,user_roles_user_id_role_key')::boolean, 'user_roles_pkey,user_roles_user_id_fkey,user_roles_user_id_role_key'::text, ((SELECT string_agg(x.conname::text, ',' ORDER BY x.conname COLLATE "C") FROM pg_constraint x WHERE x.conrelid = to_regclass('public.user_roles') AND x.contype <> 'n'))::text
  UNION ALL SELECT 'Q04-09'::text, 'app_role = admin,tester,consultant,support_admin,super_admin'::text, ((SELECT string_agg(e.enumlabel::text, ',' ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type ty ON ty.oid = e.enumtypid JOIN pg_namespace n ON n.oid = ty.typnamespace WHERE n.nspname = 'public' AND ty.typname = 'app_role') = 'admin,tester,consultant,support_admin,super_admin')::boolean, 'admin,tester,consultant,support_admin,super_admin'::text, ((SELECT string_agg(e.enumlabel::text, ',' ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type ty ON ty.oid = e.enumtypid JOIN pg_namespace n ON n.oid = ty.typnamespace WHERE n.nspname = 'public' AND ty.typname = 'app_role'))::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 10 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
